INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (3,2,1,N'国民健康保険の加入',N'会社の健康保険に入っていない人の医療保険手続き。',N'会社の健康保険やその扶養に入っていない住民。',N'港区に住み始めてから14日以内。',N'各総合支所の窓口サービス係または台場分室で届出。',N'勤務先の健康保険に加入する人は会社の手続きを確認してください。','ABROAD','AFTER_ARRIVAL','Y',1);
INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (4,2,1,N'国民年金の加入',N'会社の厚生年金に入らない人の公的年金手続き。',N'日本に住む20歳から59歳で、第2号・第3号被保険者でない人。',N'対象になった日から14日以内。',N'住所地の区役所または年金事務所で届出。',N'会社員は勤務先の厚生年金、扶養配偶者は第3号の条件を確認してください。','ABROAD','AFTER_ARRIVAL','Y',1);
INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (5,2,1,N'住民税の確認',N'前年所得と1月1日の住所を基準に税の扱いを確認。',N'前年に所得があり、課税基準日に日本国内の住所等がある人。',N'課税・申告時期は年度の案内を確認。',N'港区税務課または勤務先からの通知を確認。',N'入国初年度など前年所得がない場合は課税されるとは限りません。','ABROAD','DAILY_LIFE','Y',1);
INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (6,2,1,N'区立小中学校への入学',N'外国籍の子どもが港区立小中学校に通うための申請。',N'港区に住み、区立小中学校への入学を希望する外国籍の子ども。',N'入学時期により締切が異なるため早めに確認。',N'港区教育委員会学務課で申請。',N'日本語での手続きが難しい場合は通訳を用意してください。','ABROAD','WORK_OR_SCHOOL','Y',1);
INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (7,2,1,N'印鑑登録',N'契約等で印鑑証明書が必要な人の登録手続き。',N'港区に住民登録があり、15歳以上で意思能力がある人。',N'必要になった時に申請。',N'各総合支所区民課窓口サービス係で申請。',N'すべての人に必須ではありません。登録する印鑑の条件を確認してください。','ABROAD','DAILY_LIFE','Y',1);
INSERT INTO JL_PROCEDURE (id,region_id,category_id,title,summary,eligibility,deadline_text,method_text,notice,situation,phase_code,published,revision) VALUES (8,2,1,N'電気・ガス・水道の使用開始',N'入居した住宅でライフラインを使い始める手続き。',N'港区の住宅で電気・ガス・水道を使用する人。',N'入居日までに各事業者へ連絡。',N'契約する電力・ガス会社と東京都水道局へ申請。',N'賃貸契約書や管理会社の案内で契約先を確認してください。','ABROAD','DAILY_LIFE','Y',1);
INSERT INTO JL_PROCEDURE_I18N VALUES (3,'ko',N'국민건강보험 가입',N'회사 건강보험이 없는 사람의 의료보험 절차입니다.',N'회사 건강보험이나 그 피부양자가 아닌 주민입니다.',N'미나토구에 거주를 시작한 날부터 14일 이내입니다.',N'각 종합지소 창구서비스계 또는 다이바 분실에서 신고합니다.',N'회사 건강보험에 가입하는 사람은 회사 절차를 먼저 확인해 주세요.');
INSERT INTO JL_PROCEDURE_I18N VALUES (3,'en',N'Enroll in National Health Insurance',N'Health insurance procedures for people without employer health insurance.',N'Residents who are not covered by employee health insurance or its dependents.',N'Within 14 days after starting to live in Minato City.',N'File at a Regional City Office counter or the Daiba branch.',N'If you will join an employer plan, confirm your employer procedure.');
INSERT INTO JL_PROCEDURE_I18N VALUES (4,'ko',N'국민연금 가입',N'후생연금에 가입하지 않는 사람의 공적연금 절차입니다.',N'일본에 거주하는 20~59세 중 제2호·제3호 피보험자가 아닌 사람입니다.',N'대상이 된 날부터 14일 이내입니다.',N'주소지 구청 또는 연금사무소에서 신고합니다.',N'회사원은 후생연금, 피부양 배우자는 제3호 조건을 확인해 주세요.');
INSERT INTO JL_PROCEDURE_I18N VALUES (4,'en',N'Enroll in National Pension',N'Public pension procedures for people not covered by Employees’ Pension.',N'Residents aged 20 to 59 who are not Category II or III insured persons.',N'Within 14 days after becoming eligible.',N'File at the municipal office or a Japan Pension Service office.',N'Employees and dependent spouses should confirm their applicable category.');
INSERT INTO JL_PROCEDURE_I18N VALUES (5,'ko',N'주민세 확인',N'전년도 소득과 1월 1일 주소를 기준으로 세금 적용을 확인합니다.',N'전년도 소득이 있고 과세 기준일에 일본 주소 등이 있는 사람입니다.',N'과세·신고 시기는 해당 연도 안내를 확인합니다.',N'미나토구 세무과 또는 근무처의 통지를 확인합니다.',N'일본 입국 첫해 등 전년도 소득이 없으면 바로 과세된다고 단정할 수 없습니다.');
INSERT INTO JL_PROCEDURE_I18N VALUES (5,'en',N'Check Resident Tax',N'Check local tax treatment based on prior-year income and your address on January 1.',N'People with prior-year income and a qualifying address or property on the tax reference date.',N'Check the annual tax and filing schedule.',N'Check notices from Minato City Tax Division or your employer.',N'People arriving for the first time may not owe tax immediately if they had no prior-year income in Japan.');
INSERT INTO JL_PROCEDURE_I18N VALUES (6,'ko',N'구립 초·중학교 입학',N'외국 국적 자녀가 미나토구립 초·중학교에 다니기 위한 신청입니다.',N'미나토구에 거주하며 구립 초·중학교 입학을 희망하는 외국 국적 자녀입니다.',N'입학 시기에 따라 마감일이 다르므로 일찍 확인합니다.',N'미나토구 교육위원회 학무과에서 신청합니다.',N'일본어 절차가 어려우면 통역을 준비해 주세요.');
INSERT INTO JL_PROCEDURE_I18N VALUES (6,'en',N'Enroll in a Minato Municipal School',N'Application for foreign-national children who wish to attend a Minato municipal elementary or junior high school.',N'Foreign-national children residing in Minato City who wish to attend a municipal school.',N'Deadlines vary by enrollment period; confirm early.',N'Apply at the Minato City Board of Education School Affairs Section.',N'Arrange an interpreter if the procedure in Japanese is difficult.');
INSERT INTO JL_PROCEDURE_I18N VALUES (7,'ko',N'인감등록',N'계약 등으로 인감증명서가 필요한 사람의 등록 절차입니다.',N'미나토구 주민등록이 있고 만 15세 이상이며 의사능력이 있는 사람입니다.',N'필요할 때 신청합니다.',N'각 종합지소 구민과 창구서비스계에서 신청합니다.',N'모든 사람에게 필수는 아니며 등록할 인감의 조건을 확인해야 합니다.');
INSERT INTO JL_PROCEDURE_I18N VALUES (7,'en',N'Register a Personal Seal',N'Registration for people who need a seal certificate for contracts or other procedures.',N'Registered Minato residents aged 15 or older with decision-making capacity.',N'Apply when needed.',N'Apply at the Residents Support Section of a Regional City Office.',N'This is not mandatory for everyone; confirm the seal requirements.');
INSERT INTO JL_PROCEDURE_I18N VALUES (8,'ko',N'전기·가스·수도 사용 시작',N'입주한 주택에서 생활 인프라를 사용하기 위한 절차입니다.',N'미나토구 주택에서 전기·가스·수도를 사용할 사람입니다.',N'입주일까지 각 사업자에게 연락합니다.',N'계약할 전력·가스회사와 도쿄도 수도국에 신청합니다.',N'임대차계약서와 관리회사의 안내로 계약처를 확인해 주세요.');
INSERT INTO JL_PROCEDURE_I18N VALUES (8,'en',N'Start Electricity, Gas, and Water Service',N'Steps to start utilities at your new home in Minato City.',N'People who will use electricity, gas, and water at a Minato residence.',N'Contact each provider before the move-in date.',N'Apply to your electricity and gas providers and the Tokyo Metropolitan Waterworks Bureau.',N'Check your lease or property manager instructions for the correct providers.');
