INSERT INTO JL_STEP_I18N VALUES (9,'en',N'File at the counter',N'File the notification within 14 days.');
INSERT INTO JL_STEP_I18N VALUES (10,'ko',N'연금 구분 확인',N'제1호·제2호·제3호 중 해당 구분을 확인합니다.');
